package com.bank.portal.domain; import jakarta.persistence.*; import java.time.LocalDateTime; import lombok.*;
@Entity @Table(name="customer_card_requests") @Getter @Setter @NoArgsConstructor public class CustomerCardRequest extends BaseEntity { @ManyToOne(optional=false) @JoinColumn(name="customer_id") private Customer customer; @Enumerated(EnumType.STRING) @Column(nullable=false) private CardType cardType; @Enumerated(EnumType.STRING) @Column(nullable=false) private CustomerCardRequestStatus status; private String reviewComment; private String reviewedBy; private LocalDateTime reviewedAt; }
